using System;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using Codice.Characters;using Codice.Mechanics;using Codice.Presentation;using Codice.UI;
public static class VerifyOriginalRoll{
public static async Task<string> Run(){var run=RunDirector.Instance;var p=run.Player;if(!p.State.IsAlive)throw new Exception("Player must be alive");p.enabled=false;p.GetComponent<ActorPresentation>().enabled=false;p.SetNarrativeControlsBlocked(false);RunHUD.Instance.SetPaused(false);for(int i=0;i<6;i++){p.State.Initialize((PlayerClass)i);typeof(PlayerCharacter).GetField("nextDash",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(p,0f);if(!p.HandleDodgePress(Vector3.forward)||p.ShortDodge||p.DodgeAnimation!="Dash"||!p.IsDashing)throw new Exception("Single-press roll failed class "+i+" blocked="+p.ControlsBlocked+" stagger="+p.IsStaggered+" dash="+p.IsDashing+" scale="+Time.timeScale);if(p.HandleDodgePress(Vector3.forward))throw new Exception("Second press restarted roll");for(int n=0;n<100&&p.IsDashing;n++)await Task.Delay(50);}Debug.Log("[RollTest] PASS single Shift original Dash for all six classes; no short dodge or double tap");return "PASS original single-press roll, six classes";}}


